/**
 * Per-member project mutes. A row changes only what that member receives.
 */
import { and, asc, eq } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

/** Idempotent: muting a project the member already muted is a no-op. */
export async function muteProject(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      userId,
      projectId,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing({
      target: [projectMutes.orgId, projectMutes.userId, projectMutes.projectId],
    })
    .run();
}

/** Idempotent: unmuting a project that is not muted deletes nothing. */
export async function unmuteProject(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}

/** Projects `userId` has muted in this organization, oldest mute first. */
export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
      ),
    )
    .orderBy(asc(projectMutes.createdAt), asc(projectMutes.projectId))
    .all();

  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

export async function isProjectMuted(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<boolean> {
  const row = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .get();
  return row !== undefined;
}

