/**
 * Same guards as `getProject`: the org must be the actor's, the project must
 * exist in it, and the actor needs `project:read`.
 */
async function assertCanReadProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
}

/**
 * A muted project keeps personal kinds and strips `email` from them. Any
