export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
  /** Project the notification is about. Omit it and mute rules do not apply. */
  projectId?: ProjectId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Kinds addressed to the recipient personally. A project mute still creates
 * these, but never on the email channel. Every other kind about that project
 * is dropped for the muted member.
 */
const PERSONAL_KINDS: ReadonlySet<NotificationKind> = new Set([
  "issue_assigned",
  "comment_mention",
  "issue_overdue",
]);

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    let channels = resolveChannels(preference, flags);
    const projectId = payload.projectId ?? null;
    if (
      projectId !== null &&
      (await muteRepo.isProjectMuted(orgId, recipientId, projectId))
    ) {
      channels = channelsForMutedProject(kind, channels);
    }
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      projectId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, actor.userId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Stops this member's own traffic for one project. Repeating the call is a
 * no-op. Guarded the same way as reading the project.
 */
export async function muteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await muteRepo.muteProject(orgId, actor.userId, projectId);
}

/** Lifts the actor's own mute. Unmuting a project that is not muted is a no-op. */
export async function unmuteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await muteRepo.unmuteProject(orgId, actor.userId, projectId);
}

/** Projects this actor has muted in the organization. */
export async function listMutedProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  assertOrgScope(actor, orgId);
  return muteRepo.listMutedProjectIds(orgId, actor.userId);
}

/**
 * Same guards as `getProject`: the org must be the actor's, the project must
 * exist in it, and the actor needs `project:read`.
 */
async function assertCanReadProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
}

/**
 * A muted project keeps personal kinds and strips `email` from them. Any
 * other kind is not created. An empty list means "write no row".
 */
function channelsForMutedProject(
  kind: NotificationKind,
  channels: readonly NotificationChannel[],
): readonly NotificationChannel[] {
  if (!PERSONAL_KINDS.has(kind)) return [];
  return channels.filter((channel) => channel !== "email");
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

